fn main() -> Int {
  var data = Vec[Int]();
  {
    let m = &mut data;
    m.push(1); m.push(2);
  }
  let after_first = data.len();
  {
    let m = &mut data;
    m.push(3); m.push(4);
  }
  let after_second = data.len();
  {
    let m = &mut data;
    m.push(5);
  }
  return data.len();
}
